WITH src AS (SELECT * FROM orders WHERE customer_id IN (35, 37) AND order_date >= '2023-10-01'), orders_stats AS (SELECT YEAR(order_date) AS order_year, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, MIN(order_date) AS first_order_date FROM src GROUP BY YEAR(order_date)) SELECT order_year, partner_count, first_order_date FROM orders_stats WHERE partner_count < 6 ORDER BY partner_count
